style.css:
@-moz-document domain("chat.deepseek.com") {
/* Hace más ancha la zona de conversación */
main,
[class*="chat"],
[class*="conversation"] {
    max-width: 95vw !important;
    width: 95vw !important;
}

/* Hace más anchas las respuestas */
[class*="message"],
[class*="assistant"],
[class*="markdown"] {
    max-width: 100% !important;
}

/* Evita márgenes laterales excesivos */
.container,
[class*="container"] {
    max-width: 95vw !important;
}
}
